const std = @import("std");
const types = @import("../core/types.zig");
const ssi_mod = @import("../index/ssi.zig");

pub const Ranker = struct {
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) Ranker {
        return .{ .allocator = allocator };
    }

    pub fn rank(self: *Ranker, ssi: *ssi_mod.SSI, query: []const u32, top_k: usize) ![]types.RankedSegment {
        var candidates = try ssi.retrieveSegments(query, top_k * 10);
        defer self.allocator.free(candidates);
        var scores = try self.allocator.alloc(types.RankedSegment, candidates.len);
        for (candidates, 0..) |seg, i| {
            const seg_tokens = std.mem.bytesAsSlice(u32, ssi.mmap_ptr[seg.start..seg.end]);
            scores[i] = .{ .start = seg.start, .end = seg.end, .score = relevanceScore(query, seg_tokens) };
        }
        std.sort.block(types.RankedSegment, scores, {}, struct {
            pub fn lessThan(_: void, lhs: types.RankedSegment, rhs: types.RankedSegment) bool {
                return lhs.score > rhs.score;
            }
        }.lessThan);
        var top = try self.allocator.alloc(types.RankedSegment, top_k);
        @memcpy(top, scores[0..top_k]);
        self.allocator.free(scores);
        return top;
    }

    fn relevanceScore(query: []const u32, segment: []const u32) f32 {
        var score: f32 = 0.0;
        var overlap: usize = 0;
        for (query, 0..) |q, i| {
            for (segment) |s| {
                if (q == s) overlap += 1;
            }
            score += @floatFromInt(overlap) / @floatFromInt(segment.len) * (1.0 / @floatFromInt(i + 1));
        }
        return score;
    }
};
