const std = @import("std");

pub const MGT = struct {
    allocator: std.mem.Allocator,
    graph: std.AutoHashMap([]const u8, u32),

    pub fn init(allocator: std.mem.Allocator) !MGT {
        var graph = std.AutoHashMap([]const u8, u32).init(allocator);
        return .{ .allocator = allocator, .graph = graph };
    }

    pub fn deinit(self: *MGT) void {
        self.graph.deinit();
    }

    pub fn tokenize(self: *MGT, text: []const u8) ![]u32 {
        var tokens = std.ArrayList(u32).init(self.allocator);
        defer tokens.deinit();
        var i: usize = 0;
        while (i < text.len) {
            var max_len: usize = 0;
            var token_id: u32 = 0;
            for (1..@min(10, text.len - i + 1)) |len| {
                const substr = text[i..i + len];
                if (self.graph.get(substr)) |id| {
                    max_len = len;
                    token_id = id;
                }
            }
            if (max_len == 0) {
                const char = text[i..i + 1];
                token_id = try self.addMorph(char);
                max_len = 1;
            }
            try tokens.append(token_id);
            i += max_len;
        }
        return tokens.toOwnedSlice();
    }

    pub fn detokenize(self: *MGT, tokens: []const u32) ![]const u8 {
        var result = std.ArrayList(u8).init(self.allocator);
        defer result.deinit();
        var iter = self.graph.iterator();
        while (iter.next()) |entry| {
            for (tokens) |t| {
                if (t == entry.value_ptr.*) {
                    try result.appendSlice(entry.key_ptr.*);
                }
            }
        }
        return result.toOwnedSlice();
    }

    fn addMorph(self: *MGT, morph: []const u8) !u32 {
        const id = @truncate(self.graph.count());
        try self.graph.put(try self.allocator.dupe(u8, morph), id);
        return id;
    }
