pub const KernelIface = struct {
    pub fn invokeCapability(cap_id: u32, args: []const u64) !u64 {
        return switch (cap_id) {
            1 => try ipcSend(args[0], args[1]),
            2 => try memoryMap(args[0], args[1]),
            else => error.InvalidCap,
        };
    }

    fn ipcSend(endpoint: u64, msg: u64) !u64 {
        std.os.syscall3(.send, endpoint, msg, 0);
        return 0;
    }

    fn memoryMap(addr: u64, size: u64) !u64 {
        const ptr = std.os.mmap(@ptrFromInt(addr), size, std.os.PROT.READ | std.os.PROT.WRITE, std.os.MAP.SHARED | std.os.MAP.FIXED, -1, 0);
        return @intFromPtr(ptr);
