module RankerCore where

import Clash.Prelude

data ScoreState = ScoreState { overlap :: Unsigned 32, posBias :: Unsigned 32 }

scoreFunc :: HiddenClockResetEnable dom
          => Signal dom (Vec 128 (Unsigned 32), Vec 128 (Unsigned 32))
          -> Signal dom (Unsigned 32)
scoreFunc input = mealy scoreMealy (ScoreState 0 0) input
  where
    scoreMealy state (query, segment) = (newState, score)
      where
        overlap' = sum $ zipWith (\q s -> if q == s then 1 else 0) query segment
        posBias' = sum $ zipWith (\i _ -> 128 - i) [0..] query
        newState = ScoreState (state.overlap + overlap') (state.posBias + posBias')
