EXTENDS TLC, Integers

CONSTANT Procs
VARIABLES pc, channels

TypeOK ==
  /\ pc \in [Procs -> {"ready", "sending", "receiving", "done"}]
  /\ channels \in [Procs -> Nat]

Init ==
  /\ pc = [p \in Procs |-> "ready"]
  /\ channels = [p \in Procs |-> 0]

Send(p, q) ==
  /\ pc[p] = "ready"
  /\ pc' = [pc EXCEPT ![p] = "sending"]
  /\ channels' = [channels EXCEPT ![q] = @ + 1]

Receive(p) ==
  /\ pc[p] = "sending"
  /\ channels[p] > 0
  /\ pc' = [pc EXCEPT ![p] = "receiving"]
  /\ channels' = [channels EXCEPT ![p] = @ - 1]

Done(p) ==
  /\ pc[p] = "receiving"
  /\ pc' = [pc EXCEPT ![p] = "done"]
  /\ channels' = channels

Next ==
  \E p, q \in Procs :
    \/ Send(p, q)
    \/ Receive(p)
    \/ Done(p)

NoDeadlock == \A p \in Procs : pc[p] /= "done" => \E q \in Procs : ENABLED Send(p, q) \/ ENABLED Receive(p)

